macro_rules! Choose {
    () => {
        # [doc = " A distribution to uniformly sample elements of a slice"] # [doc = ""] # [doc = " Like [`IndexedRandom::choose`], this uniformly samples elements of a slice"] # [doc = " without modification of the slice (so called \"sampling with replacement\")."] # [doc = " This distribution object may be a little faster for repeated sampling (but"] # [doc = " slower for small numbers of samples)."] # [doc = ""] # [doc = " ## Examples"] # [doc = ""] # [doc = " Since this is a distribution, [`Rng::sample_iter`] and"] # [doc = " [`Distribution::sample_iter`] may be used, for example:"] # [doc = " ```"] # [doc = " use rand::distr::{Distribution, slice::Choose};"] # [doc = ""] # [doc = " let vowels = ['a', 'e', 'i', 'o', 'u'];"] # [doc = " let vowels_dist = Choose::new(&vowels).unwrap();"] # [doc = ""] # [doc = " // build a string of 10 vowels"] # [doc = " let vowel_string: String = vowels_dist"] # [doc = "     .sample_iter(&mut rand::rng())"] # [doc = "     .take(10)"] # [doc = "     .collect();"] # [doc = ""] # [doc = " println!(\"{}\", vowel_string);"] # [doc = " assert_eq!(vowel_string.len(), 10);"] # [doc = " assert!(vowel_string.chars().all(|c| vowels.contains(&c)));"] # [doc = " ```"] # [doc = ""] # [doc = " For a single sample, [`IndexedRandom::choose`] may be preferred:"] # [doc = " ```"] # [doc = " use rand::seq::IndexedRandom;"] # [doc = ""] # [doc = " let vowels = ['a', 'e', 'i', 'o', 'u'];"] # [doc = " let mut rng = rand::rng();"] # [doc = ""] # [doc = " println!(\"{}\", vowels.choose(&mut rng).unwrap());"] # [doc = " ```"] # [doc = ""] # [doc = " [`IndexedRandom::choose`]: crate::seq::IndexedRandom::choose"] # [doc = " [`Rng::sample_iter`]: crate::Rng::sample_iter"] # [derive (Debug , Clone , Copy)] pub struct Choose < 'a , T > { slice : & 'a [T] , range : UniformUsize , num_choices : NonZeroUsize , }
    };
}

Choose!();